from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(200, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data):
        self.UpdateMarketState(data)

        if self.IsWarmingUp:
            return

        required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        if not all(symbol in data.Bars for symbol in required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        spy_crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and spy_close > spy_sma
        )

        spy_crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and spy_close < spy_sma
        )

        aapl_red_for_three_days = self.aapl_red_streak >= 3
        aapl_rsi_above_60 = aapl_rsi > 60

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and spy_crosses_below
        ):
            self.SubmitStrategyASell()

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and aapl_rsi_above_60
        ):
            self.SubmitStrategyBSell()

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and spy_crosses_above
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            shares = math.floor(target_value / spy_close)

            if shares > 0:
                self.strategy_a_pending = True
                self.MarketOrder(self.spy, shares, tag="Strategy A buy")

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and aapl_red_for_three_days
        ):
            if float(self.Portfolio.Cash) >= 20000:
                shares = math.floor(20000 / float(data.Bars[self.aapl].Close))

                if shares > 0:
                    self.strategy_b_pending = True
                    self.MarketOrder(self.aapl, shares, tag="Strategy B buy")

    def UpdateMarketState(self, data):
        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)

            if self.spy_sma.IsReady:
                self.previous_spy_sma = float(self.spy_sma.Current.Value)

            self.previous_spy_close = spy_close

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

    def SubmitStrategyASell(self):
        self.strategy_a_pending = True
        self.MarketOrder(
            self.spy,
            -self.strategy_a_lot,
            tag="Strategy A sell"
        )

    def SubmitStrategyBSell(self):
        self.strategy_b_pending = True
        self.MarketOrder(
            self.aapl,
            -self.strategy_b_lot,
            tag="Strategy B sell"
        )

    def OnOrderEvent(self, order_event):
        fill_quantity = int(order_event.FillQuantity)

        if order_event.Symbol == self.spy:
            if fill_quantity > 0:
                self.strategy_a_lot += fill_quantity
            elif fill_quantity < 0:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_pending = False

        elif order_event.Symbol == self.aapl:
            if fill_quantity > 0:
                self.strategy_b_lot += fill_quantity
            elif fill_quantity < 0:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_pending = False
