        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_orders = {}

    def OnData(self, data):
        available = {symbol: symbol in data.Bars for symbol in self.symbols}

        spy_bar = data.Bars[self.spy] if available[self.spy] else None
        aapl_bar = data.Bars[self.aapl] if available[self.aapl] else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_data_available = all(available.values())

        if (
            not self.IsWarmingUp
            and all_data_available
            and spy_bar is not None
            and aapl_bar is not None
        ):
            spy_sma_ready = self.spy_sma.IsReady
            aapl_rsi_ready = self.aapl_rsi.IsReady

            spy_buy = (
                spy_sma_ready
                and previous_spy_close is not None
                and previous_spy_sma is not None
                and previous_spy_close <= previous_spy_sma
                and spy_bar.Close > self.spy_sma.Current.Value
            )

            spy_sell = (
                spy_sma_ready
                and previous_spy_close is not None
                and previous_spy_sma is not None
                and previous_spy_close >= previous_spy_sma
                and spy_bar.Close < self.spy_sma.Current.Value
            )

            aapl_buy = self.aapl_red_streak >= 3
            aapl_sell = aapl_rsi_ready and self.aapl_rsi.Current.Value > 60

            if self.strategy_a_lot > 0 and spy_sell:
                self._submit_sell("A", self.spy, self.strategy_a_lot)

            if self.strategy_b_lot > 0 and aapl_sell:
                self._submit_sell("B", self.aapl, self.strategy_b_lot)

            if (
                self.strategy_a_lot == 0
                and self._has_no_pending_order("A")
                and spy_buy
            ):
                shares = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue)
                    // spy_bar.Close
                )
                if shares > 0:
                    self._submit_buy("A", self.spy, shares)

            if (
                self.strategy_b_lot == 0
                and self._has_no_pending_order("B")
                and aapl_buy
                and self.Portfolio.Cash >= 20000
            ):
                shares = int(20000 // aapl_bar.Close)
                if shares > 0:
                    self._submit_buy("B", self.aapl, shares)

        if spy_bar is not None and self.spy_sma.IsReady:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _submit_buy(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=f"{strategy}_BUY")
        self.pending_orders[ticket.OrderId] = strategy

    def _submit_sell(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, -quantity, tag=f"{strategy}_SELL")
        self.pending_orders[ticket.OrderId] = strategy

    def _has_no_pending_order(self, strategy):
        return strategy not in self.pending_orders.values()

    def OnOrderEvent(self, order_event):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_lot += order_event.FillQuantity
            elif strategy == "B":
                self.strategy_b_lot += order_event.FillQuantity

            self.strategy_a_lot = max(0, self.strategy_a_lot)
            self.strategy_b_lot = max(0, self.strategy_b_lot)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_event.OrderId]
